-- Canonical brokerage transactions and immutable, purpose-scoped execution documents.
begin;
create table kalling_private.execution_transactions(
 id uuid primary key default gen_random_uuid(),firm_id uuid not null references public.kalling_firms(id),listing_id uuid not null references public.kalling_listings(id),
 portal_id uuid not null references public.kalling_portals(id),buyer_id uuid not null references public.kalling_buyers(id),offer_id uuid not null references public.kalling_offers(id),offer_version integer not null check(offer_version>0),
 state text not null check(state in ('Planning','LOI reviewed','Abandoned','Closed')),revision integer not null check(revision>0),data jsonb not null check(octet_length(data::text)<1500000),created_at timestamptz not null default now());
create unique index execution_one_active on kalling_private.execution_transactions(listing_id) where state in ('Planning','LOI reviewed');
create table kalling_private.execution_participants(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references kalling_private.execution_transactions(id),email text not null,name text not null,role text not null check(role in ('Lawyer','CPA','Lender','Other specialist')),purpose text not null,coordinator text not null,status text not null check(status in ('Pending','Active','Revoked')),expires_at timestamptz not null,user_id uuid references auth.users(id),token_hash text unique not null,accepted_at timestamptz,identity_allowed boolean not null default false);
create table kalling_private.execution_files(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references kalling_private.execution_transactions(id),family uuid not null,version integer not null check(version>0),object_path text not null unique,portal_file_id uuid references public.kalling_portal_files(id),status text not null check(status in ('Reserved','Stored')),uploaded_by uuid not null references auth.users(id),created_at timestamptz not null default now(),data jsonb not null,grants text[] not null default '{}',review jsonb,unique(transaction_id,family,version));
create table kalling_private.execution_events(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references kalling_private.execution_transactions(id),file_id uuid,actor uuid,event text not null,at timestamptz not null default now(),ticket uuid,object_path text,note text not null default '');
create index execution_event_ticket on kalling_private.execution_events(ticket,actor) where ticket is not null;
alter table kalling_private.execution_transactions enable row level security;
alter table kalling_private.execution_participants enable row level security;
alter table kalling_private.execution_files enable row level security;
alter table kalling_private.execution_events enable row level security;
revoke all on kalling_private.execution_transactions,kalling_private.execution_participants,kalling_private.execution_files,kalling_private.execution_events from public,anon,authenticated;
create function kalling_private.execution_role(p_id uuid) returns text language sql stable security definer set search_path='' as $$
 select case
 when t.firm_id=kalling_private.house() and kalling_private.role_for(t.firm_id) in ('owner','admin','analyst') then 'advisor'
 when t.firm_id=kalling_private.house() and kalling_private.role_for(t.firm_id)='viewer' then 'viewer'
 when kalling_private.portal_role(t.portal_id)='seller' then 'seller'
 when t.state<>'Abandoned' and t.buyer_id=(kalling_private.my_buyer()).id and (kalling_private.my_buyer()).status<>'Restricted' and exists(select 1 from public.kalling_access a where a.listing_id=t.listing_id and a.buyer_id=t.buyer_id and a.status='Approved') then 'buyer'
 when t.state<>'Abandoned' then (select p.id::text from kalling_private.execution_participants p join auth.users u on u.id=p.user_id where p.transaction_id=t.id and p.status='Active' and p.expires_at>now() and p.user_id=auth.uid() and u.email_confirmed_at is not null and lower(u.email)=p.email)
 end from kalling_private.execution_transactions t where t.id=p_id and auth.uid() is not null
$$;
create function kalling_private.execution_current(p_file uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from kalling_private.execution_files f where f.id=p_file and f.status='Stored' and not exists(select 1 from kalling_private.execution_files newer where newer.transaction_id=f.transaction_id and newer.family=f.family and newer.version>f.version and newer.status='Stored') and (f.portal_file_id is null or exists(select 1 from public.kalling_portal_files p where p.id=f.portal_file_id and p.status='stored' and p.object_path=f.object_path and p.sha256=f.data->>'sha256')))
$$;
create function kalling_private.execution_source(p_tx uuid,p jsonb) returns boolean language plpgsql stable security definer set search_path='' as $$ begin
 return coalesce(jsonb_typeof(p)='object' and (p->>'page')::integer between 1 and 5000 and length(trim(p->>'excerpt')) between 5 and 5000 and exists(select 1 from kalling_private.execution_files f where f.id=(p->>'fileId')::uuid and f.transaction_id=p_tx and kalling_private.execution_current(f.id)),false);
 exception when others then return false;end $$;
create function kalling_private.execution_sources(p_tx uuid,p jsonb) returns boolean language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_typeof(p)='array' and jsonb_array_length(p)>0 and not exists(select 1 from jsonb_array_elements(p) s where not kalling_private.execution_source(p_tx,s)),false)
$$;
create function kalling_private.execution_file_allowed(p_file uuid) returns boolean language plpgsql stable security definer set search_path='' as $$
 declare f kalling_private.execution_files;t kalling_private.execution_transactions;r text;h jsonb;begin
 select * into f from kalling_private.execution_files where id=p_file;if not found or not kalling_private.execution_current(f.id) then return false;end if;
 select * into t from kalling_private.execution_transactions where id=f.transaction_id;r=kalling_private.execution_role(t.id);if r is null then return false;end if;if r in ('advisor','viewer') then return true;end if;
 if f.review is null or not (r=any(f.grants)) or (f.data->>'content'='Restricted lender' and r='seller') then return false;end if;
 if f.data->>'content'='Named counterparties' and (t.data#>'{identity,seller}' is null or t.data#>'{identity,buyer}' is null or (r not in ('buyer','seller') and not exists(select 1 from kalling_private.execution_participants p where p.id::text=r and p.identity_allowed))) then return false;end if;
 if t.state='Closed' then h=t.data->'closes'->-1->'handover';return case when r='buyer' then h->'buyerFiles' ? f.id::text when r='seller' then h->'sellerFiles' ? f.id::text else h->'guestIds' ? r end;end if;
 return true;end $$;
create function kalling_private.execution_deadline(p jsonb) returns boolean language plpgsql immutable set search_path='' as $$
 declare d date;n integer;step integer=0;kind text=p->>'kind';begin
 if kind='Unknown' then return length(trim(p->>'reason')) between 5 and 400;end if;
 if kind='Date' then return p->>'timezone'='America/New_York' and to_char((p->>'date')::date,'YYYY-MM-DD')=p->>'date';end if;
 if kind='Time' then return p->>'timezone'='America/New_York' and p->>'instant'~'^\d{4}-\d{2}-\d{2}T.*(Z|[+-]\d{2}:\d{2})$' and (p->>'instant')::timestamptz is not null;end if;
 if kind<>'Relative' or p->>'calendar' not in ('Calendar days','Business days') or jsonb_typeof(p->'includeAnchor')<>'boolean' or jsonb_typeof(p->'holidays')<>'array' or length(p->>'confirmedBy')<2 then return false;end if;
 d=(p->>'anchor')::date;n=(p->>'days')::integer;if n<0 or n>3650 then return false;end if;
 if (p->>'includeAnchor')::boolean and n>0 and (p->>'calendar'='Calendar days' or (extract(dow from d) not in (0,6) and not (p->'holidays' ? to_char(d,'YYYY-MM-DD')))) then n=n-1;end if;
 while n>0 loop d=d+1;step=step+1;if step>6000 then return false;end if;if p->>'calendar'='Calendar days' or (extract(dow from d) not in (0,6) and not (p->'holidays' ? to_char(d,'YYYY-MM-DD'))) then n=n-1;end if;end loop;
 return to_char(d,'YYYY-MM-DD')=p->>'confirmedDate';exception when others then return false;end $$;
create function kalling_private.execution_loi_ok(t kalling_private.execution_transactions) returns boolean language sql stable security definer set search_path='' as $$
 select coalesce(t.data->'lois'->-1->'review' is not null and kalling_private.execution_source(t.id,(t.data->'lois'->-1)#>'{review,source}') and exists(select 1 from jsonb_array_elements(t.data->'lois'->-1->'signatories') s where s->>'side'='buyer') and exists(select 1 from jsonb_array_elements(t.data->'lois'->-1->'signatories') s where s->>'side'='seller') and not exists(select 1 from jsonb_array_elements(t.data->'lois'->-1->'signatories') s where not kalling_private.execution_source(t.id,s->'source')),false)
$$;
create function kalling_private.execution_save(t kalling_private.execution_transactions,p_data jsonb,p_action text,p_note text) returns void language plpgsql security definer set search_path='' as $$
 declare e jsonb=jsonb_build_object('id',gen_random_uuid(),'action',p_action,'by',kalling_private.actor_name(),'at',now(),'note',left(coalesce(p_note,''),2000));begin
 update kalling_private.execution_transactions set state=p_data->>'state',revision=t.revision+1,data=p_data||jsonb_build_object('revision',t.revision+1,'history',coalesce(t.data->'history','[]')||jsonb_build_array(e)) where id=t.id;
 insert into kalling_private.execution_events(transaction_id,actor,event,note) values(t.id,auth.uid(),p_action,left(coalesce(p_note,''),2000));end $$;
create function kalling_private.execution_safe(p text,min_length integer default 0,max_length integer default 2000) returns boolean language sql immutable set search_path='' as $$ select coalesce(length(trim(p)) between min_length and max_length and p!~*'(social security|routing number|bank account number|wire instructions|credit authorization|\m[0-9]{3}-[0-9]{2}-[0-9]{4}\M)',false) $$;
create function kalling_private.execution_projection(p_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
 declare t kalling_private.execution_transactions;r text;d jsonb;items jsonb;files jsonb;begin
 select * into t from kalling_private.execution_transactions where id=p_id;r=kalling_private.execution_role(p_id);if r is null then raise exception 'Transaction access denied' using errcode='42501';end if;d=t.data;
 if r in ('advisor','viewer') then
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'email',p.email,'name',p.name,'role',p.role,'purpose',p.purpose,'coordinator',p.coordinator,'status',p.status,'expiresAt',p.expires_at,'acceptedAt',p.accepted_at,'identityAllowed',p.identity_allowed)),'[]') into items from kalling_private.execution_participants p where transaction_id=t.id;d=d||jsonb_build_object('participants',items);
 else
 d=d-'buyerId'-'firmId'-'companyId'-'originalEstimate'-'stopReason'||jsonb_build_object('buyerId','','firmId','','companyId','','originalEstimate',null,'identity','{}'::jsonb,'participants','[]'::jsonb,'history','[]'::jsonb,'comparables','[]'::jsonb);
 select coalesce(jsonb_agg(l),'[]') into items from jsonb_array_elements(t.data->'lois') l where kalling_private.execution_file_allowed((l->>'fileId')::uuid);d=jsonb_set(d,'{lois}',items);
 select coalesce(jsonb_agg(o),'[]') into items from jsonb_array_elements(t.data->'obligations') o where kalling_private.execution_file_allowed((o#>>'{source,fileId}')::uuid);d=jsonb_set(d,'{obligations}',items);
 select coalesce(jsonb_agg((i-'history')||jsonb_build_object('history','[]'::jsonb,'sources',(select coalesce(jsonb_agg(s),'[]') from jsonb_array_elements(i->'sources') s where kalling_private.execution_file_allowed((s->>'fileId')::uuid)))),'[]') into items from jsonb_array_elements(t.data->'items') i where i->'audience' ? r;d=jsonb_set(d,'{items}',items);
 select coalesce(jsonb_agg((i-'history')||jsonb_build_object('history','[]'::jsonb,'sources',(select coalesce(jsonb_agg(s),'[]') from jsonb_array_elements(i->'sources') s where kalling_private.execution_file_allowed((s->>'fileId')::uuid)))),'[]') into items from jsonb_array_elements(t.data->'conditions') i where i->'audience' ? r;d=jsonb_set(d,'{conditions}',items);
 if r<>'seller' then d=jsonb_set(d,'{cases}','[]');end if;
 select coalesce(jsonb_agg((c-'evidence'-'handover')||jsonb_build_object('evidence',coalesce((select jsonb_agg(s) from jsonb_array_elements(c->'evidence') s where kalling_private.execution_file_allowed((s->>'fileId')::uuid)),'[]'),'handover',jsonb_build_object('guestIds','[]'::jsonb,'buyerFiles','[]'::jsonb,'sellerFiles','[]'::jsonb))),'[]') into items from jsonb_array_elements(t.data->'closes') c;d=jsonb_set(d,'{closes}',items);
 if d->'closePackage' is not null then d=jsonb_set(d,'{closePackage,note}','"Prepared for a completion review."');end if;
 end if;
 select coalesce(jsonb_agg(f.data||jsonb_build_object('id',f.id,'transactionId',f.transaction_id,'family',f.family,'version',f.version,'status',f.status,'createdAt',f.created_at,'review',f.review,'grants',case when r in ('advisor','viewer') then to_jsonb(f.grants) else '[]'::jsonb end)),'[]') into files from kalling_private.execution_files f where f.transaction_id=t.id and (r in ('advisor','viewer') or kalling_private.execution_file_allowed(f.id));
 return jsonb_build_object('transaction',d,'files',files,'role',r);end $$;
create function public.kalling_execution_rows() returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(kalling_private.execution_projection(t.id)),'[]') from kalling_private.execution_transactions t where kalling_private.execution_role(t.id) is not null
$$;
create function public.kalling_execution_start(p_offer uuid,p_version integer,p_portal uuid) returns uuid language plpgsql security definer set search_path='' as $$
 declare o public.kalling_offers;l public.kalling_listings;p public.kalling_portals;v jsonb;i uuid=gen_random_uuid();d jsonb;w jsonb;c jsonb;estimate jsonb;begin
 perform kalling_private.need_advisor();select * into o from public.kalling_offers where id=p_offer for update;select * into l from public.kalling_listings where id=o.listing_id for update;select * into p from public.kalling_portals where id=p_portal;
 if o.id is null or o.current_version<>p_version or l.status not in ('Live','Under LOI') or o.status in ('Withdrawn','Declined') or p.id is null or p.firm_id<>kalling_private.house() or p.status<>'Active' or not exists(select 1 from public.kalling_listing_private x where x.listing_id=l.id and x.company_id=p.company_id) or not exists(select 1 from public.kalling_access a join public.kalling_buyers b on b.id=a.buyer_id where a.listing_id=l.id and a.buyer_id=o.buyer_id and a.status='Approved' and b.status<>'Restricted') then raise exception 'Select a current offer, approved buyer and active seller portal.';end if;
 if not exists(select 1 from kalling_private.offer_shares s where s.offer_id=o.id and s.version=p_version) or not exists(select 1 from kalling_private.offer_instructions x where x.offer_id=o.id and x.version=p_version) then raise exception 'Share the exact offer version and record the owner instruction first.';end if;
 select terms into v from kalling_private.offer_versions where offer_id=o.id and version=p_version;if v->>'expiresOn'<to_char(current_date,'YYYY-MM-DD') then raise exception 'This offer has expired.';end if;
 select data into w from public.kalling_workspaces where firm_id=p.firm_id;select x into c from jsonb_array_elements(coalesce(w->'companies','[]')) x where x->>'id'=p.company_id;
 estimate=case when c#>'{recast,version}' is not null then jsonb_build_object('version',c#>>'{recast,version}','low',null,'mid',null,'high',null,'asOf',c#>>'{recast,updatedAt}','source','Frozen original recast; numerical estimate not previously saved','recast',c->'recast') else 'null'::jsonb end;
 d=jsonb_build_object('id',i,'fictional',l.sample,'firmId',p.firm_id,'listingId',l.id,'companyId',p.company_id,'portalId',p.id,'buyerId',o.buyer_id,'buyerLabel',kalling_private.dataroom_label(l.id,o.buyer_id),'offerId',o.id,'offerVersion',p_version,'terms',v,'state','Planning','revision',1,'createdAt',now(),'createdBy',kalling_private.actor_name(),'lois','[]'::jsonb,'obligations','[]'::jsonb,'participants','[]'::jsonb,'identity','{}'::jsonb,'items','[]'::jsonb,'conditions','[]'::jsonb,'closes','[]'::jsonb,'cases','[]'::jsonb,'comparables','[]'::jsonb,'originalEstimate',estimate,'history','[]'::jsonb);
 insert into kalling_private.execution_transactions(id,firm_id,listing_id,portal_id,buyer_id,offer_id,offer_version,state,revision,data) values(i,p.firm_id,l.id,p.id,o.buyer_id,o.id,p_version,'Planning',1,d);return i;end $$;
create function public.kalling_execution_loi(p_transaction uuid,p_revision integer,p_action text,p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
 declare t kalling_private.execution_transactions;d jsonb;r text;l jsonb;sig jsonb;n integer;o jsonb;begin
 select * into t from kalling_private.execution_transactions where id=p_transaction for update;r=kalling_private.execution_role(t.id);if r is null then raise exception 'Transaction access denied' using errcode='42501';end if;
 if t.revision<>p_revision then raise exception 'This transaction changed. Reload before saving.';end if;if t.state in ('Closed','Abandoned') then raise exception 'This transaction is an archive.';end if;d=t.data;
 if p_action='identity' then
 if not ((r=p->>'side' and coalesce((p->>'external')::boolean,false)=false) or (r='advisor' and (p->>'external')::boolean)) or p->>'side' not in ('buyer','seller') or not kalling_private.execution_source(t.id,p->'source') or not kalling_private.execution_safe(p->>'note',20,2000) then raise exception 'Record your own permission or an evidenced external instruction as a reviewer.';end if;
 d=jsonb_set(d,array['identity',p->>'side'],jsonb_build_object('source',p->'source','note',p->>'note','reviewer',kalling_private.actor_name(),'external',p->'external','at',now()));
 else
 if r<>'advisor' then raise exception 'Only a brokerage reviewer can do this' using errcode='42501';end if;
 if p_action='loi' then
 if (p->>'offerVersion')::integer is distinct from t.offer_version or not exists(select 1 from kalling_private.execution_files f where f.id=(p->>'fileId')::uuid and f.transaction_id=t.id and f.data->>'kind'='LOI' and kalling_private.execution_current(f.id)) or not kalling_private.execution_safe(p->>'sellerEntity',2,160) or not kalling_private.execution_safe(p->>'buyerEntity',2,160) or not kalling_private.execution_safe(p->>'structure',5,1000) or coalesce(to_char((p->>'executionDate')::date,'YYYY-MM-DD')=p->>'executionDate',false)=false then raise exception 'Record the current LOI, legal entities and stated execution date.';end if;
 if jsonb_typeof(p->'signatories')<>'array' or jsonb_array_length(p->'signatories')<2 or not exists(select 1 from jsonb_array_elements(p->'signatories') x where x->>'side'='seller') or not exists(select 1 from jsonb_array_elements(p->'signatories') x where x->>'side'='buyer') then raise exception 'Record both required signatories.';end if;
 for sig in select * from jsonb_array_elements(p->'signatories') loop if not kalling_private.execution_safe(sig->>'name',2,160) or not kalling_private.execution_safe(sig->>'role',2,160) or sig#>>'{source,fileId}'<>p->>'fileId' or not kalling_private.execution_source(t.id,sig->'source') then raise exception 'Each signature needs a current file, page, excerpt and role.';end if;end loop;
 n=jsonb_array_length(d->'lois')+1;l=(p-'review'-'version'-'createdAt'-'createdBy')||jsonb_build_object('version',n,'createdAt',now(),'createdBy',kalling_private.actor_name());d=jsonb_set(d,'{lois}',d->'lois'||jsonb_build_array(l))||jsonb_build_object('state','Planning');
 elsif p_action='confirm_loi' then
 l=d->'lois'->-1;if l is null or p#>>'{source,fileId}'<>l->>'fileId' or not kalling_private.execution_source(t.id,p->'source') or not kalling_private.execution_safe(p->>'note',20,2000) or exists(select 1 from jsonb_array_elements(l->'signatories') s where not kalling_private.execution_source(t.id,s->'source')) then raise exception 'Review current external signature evidence and explain the confirmation.';end if;
 l=l||jsonb_build_object('review',jsonb_build_object('source',p->'source','note',p->>'note','reviewer',kalling_private.actor_name(),'at',now()));d=jsonb_set(d,array['lois',(jsonb_array_length(d->'lois')-1)::text],l)||jsonb_build_object('state','LOI reviewed');update public.kalling_listings set status='Under LOI',updated_at=now() where id=t.listing_id;
 elsif p_action='obligation' then
 if not kalling_private.execution_loi_ok(t) or not kalling_private.execution_source(t.id,p->'source') or p#>>'{source,fileId}'<>d->'lois'->-1->>'fileId' or not kalling_private.execution_deadline(p->'deadline') or not kalling_private.execution_safe(p->>'title',3,160) then raise exception 'Confirm an obligation against the current reviewed LOI and calendar convention.';end if;
 select x into o from jsonb_array_elements(d->'obligations') x where x->>'id'=p->>'supersedes';if p->>'supersedes' is not null and o is null then raise exception 'The superseded obligation is missing.';end if;
 l=jsonb_build_object('id',gen_random_uuid(),'title',p->>'title','source',p->'source','deadline',p->'deadline','version',coalesce((o->>'version')::integer,0)+1,'loiVersion',d->'lois'->-1->'version','confirmedBy',kalling_private.actor_name(),'at',now(),'supersedes',p->>'supersedes');d=jsonb_set(d,'{obligations}',d->'obligations'||jsonb_build_array(l));
 elsif p_action='abandon' then
 if not kalling_private.execution_safe(p->>'note',20,2000) then raise exception 'Record why negotiations stopped.';end if;d=d||jsonb_build_object('state','Abandoned','stopReason',p->>'note');update kalling_private.execution_participants set status='Revoked' where transaction_id=t.id;
 else raise exception 'Unknown LOI action';end if;end if;
 d=d-'closePackage';perform kalling_private.execution_save(t,d,p_action,coalesce(p->>'note',p->>'title',''));return kalling_private.execution_projection(t.id);end $$;


create function public.kalling_execution_invite(p_transaction uuid,p jsonb) returns text language plpgsql security definer set search_path='' as $$
 declare t kalling_private.execution_transactions;token text=replace(gen_random_uuid()::text||gen_random_uuid()::text,'-','');begin
 select * into t from kalling_private.execution_transactions where id=p_transaction for update;
 if kalling_private.execution_role(t.id) is distinct from 'advisor' or t.state in ('Closed','Abandoned') then raise exception 'Invitation access denied' using errcode='42501';end if;
 if not coalesce((p->>'recipientReviewed')::boolean,false) or p->>'email'!~'^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or p->>'role' not in ('Lawyer','CPA','Lender','Other specialist') or not kalling_private.execution_safe(p->>'name',2,120) or not kalling_private.execution_safe(p->>'purpose',10,600) or not kalling_private.execution_safe(p->>'coordinator',2,120) or (p->>'expiresAt')::timestamptz<=now() or (p->>'expiresAt')::timestamptz>now()+interval '90 days' then raise exception 'Review the recipient, role, purpose, internal coordinator and expiry.';end if;
 insert into kalling_private.execution_participants(transaction_id,email,name,role,purpose,coordinator,status,expires_at,token_hash,identity_allowed) values(t.id,lower(p->>'email'),p->>'name',p->>'role',p->>'purpose',p->>'coordinator','Pending',(p->>'expiresAt')::timestamptz,md5(token),coalesce((p->>'identityAllowed')::boolean,false));
 perform kalling_private.execution_save(t,t.data-'closePackage','Specialist invitation prepared','Recipient reviewed; no message sent.');return token;end $$;
create function public.kalling_execution_accept_invite(p_token text) returns uuid language plpgsql security definer set search_path='' as $$
 declare p kalling_private.execution_participants;begin
 select * into p from kalling_private.execution_participants where token_hash=md5(p_token) for update;
 if p.id is null or p.status<>'Pending' or p.expires_at<=now() or p.accepted_at is not null or not exists(select 1 from auth.users u where u.id=auth.uid() and lower(u.email)=p.email and u.email_confirmed_at is not null) or not exists(select 1 from kalling_private.execution_transactions t where t.id=p.transaction_id and t.state in ('Planning','LOI reviewed')) then raise exception 'This invitation is expired, used, revoked or belongs to another email.';end if;
 update kalling_private.execution_participants set user_id=auth.uid(),status='Active',accepted_at=now() where id=p.id;return p.transaction_id;end $$;
create function public.kalling_execution_revoke(p_transaction uuid,p_participant uuid,p_note text) returns void language plpgsql security definer set search_path='' as $$
 declare t kalling_private.execution_transactions;begin select * into t from kalling_private.execution_transactions where id=p_transaction for update;
 if kalling_private.execution_role(t.id) is distinct from 'advisor' or not kalling_private.execution_safe(p_note,10,1000) then raise exception 'Revocation access denied' using errcode='42501';end if;
 update kalling_private.execution_participants set status='Revoked' where id=p_participant and transaction_id=t.id;perform kalling_private.execution_save(t,t.data-'closePackage','Specialist access revoked',p_note);end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('kalling-execution','kalling-execution',false,10485760,array['application/pdf']) on conflict(id) do nothing;
create function public.kalling_execution_file_prepare(p_transaction uuid,p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
 declare t kalling_private.execution_transactions;i uuid=gen_random_uuid();fam uuid=coalesce(nullif(p->>'family','')::uuid,gen_random_uuid());v integer;path text;r text;begin
 select * into t from kalling_private.execution_transactions where id=p_transaction for update;r=kalling_private.execution_role(t.id);
 if r is null or r='viewer' or t.state in ('Closed','Abandoned') then raise exception 'Document upload is not permitted' using errcode='42501';end if;
 if not kalling_private.execution_safe(p->>'name',1,200) or p->>'mime'<>'application/pdf' or (p->>'size')::bigint not between 1 and 10485760 or p->>'sha256'!~'^[0-9a-f]{64}$' or p->>'kind' not in ('LOI','Diligence','Closing evidence','Lease','License','Other') or p->>'content' not in ('Confidential','Named counterparties','Restricted lender') then raise exception 'Use a PDF no larger than 10 MB and choose its purpose.';end if;
 select coalesce(max(version),0)+1 into v from kalling_private.execution_files where transaction_id=t.id and family=fam;
 path=t.id::text||'/'||i::text||'.pdf';insert into kalling_private.execution_files(id,transaction_id,family,version,object_path,status,uploaded_by,data) values(i,t.id,fam,v,path,'Reserved',auth.uid(),jsonb_build_object('name',p->>'name','mime','application/pdf','size',(p->>'size')::bigint,'sha256',p->>'sha256','kind',p->>'kind','content',p->>'content','uploadedBy',r));return jsonb_build_object('id',i,'path',path);end $$;
create function public.kalling_execution_file_finish(p_file uuid) returns void language plpgsql security definer set search_path='' as $$
 declare f kalling_private.execution_files;t kalling_private.execution_transactions;items jsonb;begin
 select * into f from kalling_private.execution_files where id=p_file for update;select * into t from kalling_private.execution_transactions where id=f.transaction_id for update;
 if f.id is null or f.uploaded_by<>auth.uid() or kalling_private.execution_role(t.id) is null or kalling_private.execution_role(t.id)='viewer' or t.state in ('Closed','Abandoned') then raise exception 'Upload completion denied' using errcode='42501';end if;
 if not exists(select 1 from storage.objects o where o.bucket_id='kalling-execution' and o.name=f.object_path and (o.metadata->>'size')::bigint=(f.data->>'size')::bigint and o.metadata->>'mimetype'='application/pdf') then raise exception 'The stored PDF does not match its reserved metadata.';end if;
 if f.status='Stored' then return;end if;update kalling_private.execution_files set status='Stored' where id=f.id;
 select coalesce(jsonb_agg(case when exists(select 1 from jsonb_array_elements(i->'sources') s join kalling_private.execution_files old on old.id=(s->>'fileId')::uuid where old.transaction_id=t.id and old.family=f.family and old.id<>f.id) then (i-'review')||jsonb_build_object('status','Changes needed','revision',(i->>'revision')::integer+1,'nextAction','Review the replacement document and submit a new response.') else i end),'[]') into items from jsonb_array_elements(t.data->'items') i;
 perform kalling_private.execution_save(t,jsonb_set(t.data-'closePackage','{items}',items),'Document stored','Upload does not resolve a request.');end $$;
create function public.kalling_execution_file_review(p_file uuid,p_note text) returns void language plpgsql security definer set search_path='' as $$
 declare f kalling_private.execution_files;begin select * into f from kalling_private.execution_files where id=p_file for update;if kalling_private.execution_role(f.transaction_id) is distinct from 'advisor' or not kalling_private.execution_current(f.id) or not kalling_private.execution_safe(p_note,10,1000) then raise exception 'Review the current document as a brokerage reviewer.';end if;update kalling_private.execution_files set review=jsonb_build_object('by',kalling_private.actor_name(),'at',now(),'note',p_note) where id=f.id;end $$;
create function public.kalling_execution_file_grant(p_file uuid,p_recipients text[],p_permission jsonb,p_note text) returns void language plpgsql security definer set search_path='' as $$
 declare f kalling_private.execution_files;t kalling_private.execution_transactions;r text;begin select * into f from kalling_private.execution_files where id=p_file for update;select * into t from kalling_private.execution_transactions where id=f.transaction_id for update;
 if kalling_private.execution_role(t.id) is distinct from 'advisor' or t.state in ('Closed','Abandoned') or not kalling_private.execution_current(f.id) or f.review is null or not kalling_private.execution_source(t.id,p_permission) or not kalling_private.execution_safe(p_note,20,1000) then raise exception 'Review this document and record permission for the exact version.';end if;
 foreach r in array p_recipients loop
 if r not in ('seller','buyer') and not exists(select 1 from kalling_private.execution_participants p where p.transaction_id=t.id and p.id::text=r and p.status='Active' and p.expires_at>now()) then raise exception 'Choose current transaction participants.';end if;
 if f.data->>'content'='Restricted lender' and r='seller' then raise exception 'Restricted lender material is not shared with the seller.';end if;
 if f.data->>'content'='Named counterparties' and (t.data#>'{identity,seller}' is null or t.data#>'{identity,buyer}' is null or (r not in ('seller','buyer') and not exists(select 1 from kalling_private.execution_participants p where p.id::text=r and p.identity_allowed))) then raise exception 'Confirm both identity permissions before sharing a named document.';end if;end loop;
 update kalling_private.execution_files set grants=p_recipients where id=f.id;perform kalling_private.execution_save(t,t.data-'closePackage','Document permission recorded',p_note);end $$;
create function public.kalling_execution_file_open(p_file uuid) returns jsonb language plpgsql security definer set search_path='' as $$
 declare f kalling_private.execution_files;ticket uuid=gen_random_uuid();allowed boolean;begin
 select * into f from kalling_private.execution_files where id=p_file;allowed=kalling_private.execution_file_allowed(p_file);
 if f.id is not null then insert into kalling_private.execution_events(transaction_id,file_id,actor,event,ticket,object_path) values(f.transaction_id,f.id,auth.uid(),case when allowed then 'opened' else 'denied' end,case when allowed then ticket end,f.object_path);end if;
 if not allowed then return jsonb_build_object('allowed',false);end if;
 return jsonb_build_object('allowed',true,'ticket',ticket,'path',f.object_path,'bucket',case when f.portal_file_id is null then 'kalling-execution' else 'kalling-portal' end);end $$;
create function kalling_private.execution_ticket_ok(p_path text) returns boolean language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and exists(select 1 from kalling_private.execution_events e join kalling_private.execution_files f on f.id=e.file_id and f.object_path=e.object_path where e.actor=auth.uid() and e.event='opened' and e.ticket is not null and e.at>now()-interval '2 minutes' and e.at<=now() and e.object_path=p_path and kalling_private.execution_file_allowed(f.id))
$$;
create function kalling_private.execution_upload_ok(p_path text) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from kalling_private.execution_files f join kalling_private.execution_transactions t on t.id=f.transaction_id where f.object_path=p_path and f.status='Reserved' and f.uploaded_by=auth.uid() and f.created_at>now()-interval '1 day' and t.state in ('Planning','LOI reviewed') and kalling_private.execution_role(f.transaction_id) is not null and kalling_private.execution_role(f.transaction_id)<>'viewer') $$;
create policy execution_file_insert on storage.objects for insert to authenticated with check(bucket_id='kalling-execution' and kalling_private.execution_upload_ok(name));
create policy execution_file_read on storage.objects for select to authenticated using(bucket_id in ('kalling-execution','kalling-portal') and storage.allow_only_operation('object.get_authenticated') and kalling_private.execution_ticket_ok(name));
revoke all on function kalling_private.execution_role(uuid),kalling_private.execution_current(uuid),kalling_private.execution_source(uuid,jsonb),kalling_private.execution_sources(uuid,jsonb),kalling_private.execution_file_allowed(uuid),kalling_private.execution_deadline(jsonb),kalling_private.execution_loi_ok(kalling_private.execution_transactions),kalling_private.execution_save(kalling_private.execution_transactions,jsonb,text,text),kalling_private.execution_safe(text,integer,integer),kalling_private.execution_projection(uuid) from public,anon,authenticated;
revoke all on function kalling_private.execution_ticket_ok(text),kalling_private.execution_upload_ok(text) from public,anon;grant execute on function kalling_private.execution_ticket_ok(text),kalling_private.execution_upload_ok(text) to authenticated;
revoke all on function public.kalling_execution_rows(),public.kalling_execution_start(uuid,integer,uuid),public.kalling_execution_loi(uuid,integer,text,jsonb),public.kalling_execution_invite(uuid,jsonb),public.kalling_execution_accept_invite(text),public.kalling_execution_revoke(uuid,uuid,text),public.kalling_execution_file_prepare(uuid,jsonb),public.kalling_execution_file_finish(uuid),public.kalling_execution_file_review(uuid,text),public.kalling_execution_file_grant(uuid,text[],jsonb,text),public.kalling_execution_file_open(uuid) from public,anon;
grant execute on function public.kalling_execution_rows(),public.kalling_execution_start(uuid,integer,uuid),public.kalling_execution_loi(uuid,integer,text,jsonb),public.kalling_execution_invite(uuid,jsonb),public.kalling_execution_accept_invite(text),public.kalling_execution_revoke(uuid,uuid,text),public.kalling_execution_file_prepare(uuid,jsonb),public.kalling_execution_file_finish(uuid),public.kalling_execution_file_review(uuid,text),public.kalling_execution_file_grant(uuid,text[],jsonb,text),public.kalling_execution_file_open(uuid) to authenticated;
